mappings.INQUIRY.response:
body.ValidateAccountResponse.status = "ACTIVE" and $type(body.ValidateAccountResponse.accountName) = "string"
    and body.ValidateAccountResponse.accountName != "" and $type(body.ValidateAccountResponse.verifyRef) = "string"
  ? {"outcome": "SUCCESS", "partnerRef": body.ValidateAccountResponse.verifyRef,
     "attributes": {"holderName": $uppercase($substring($trim(body.ValidateAccountResponse.accountName), 0, 1)) & "."}}
: body.fault.`@code` = "Client" and $type(body.fault.detail.code) = "string" and body.fault.detail.code != ""
  ? {"outcome": "FAILED", "code": body.fault.detail.code, "message": body.fault.detail.message}
: {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"}

mappings.PAY.response:
body.TransferResponse.status = "SUCCESS" and $type(body.TransferResponse.bankRef) = "string" and body.TransferResponse.bankRef != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.TransferResponse.bankRef, "code": body.TransferResponse.code}
: body.TransferResponse.status = "PENDING"
  ? {"outcome": "PENDING", "partnerRef": body.TransferResponse.bankRef, "code": body.TransferResponse.code}
: body.fault.`@code` = "Client" and $type(body.fault.detail.code) = "string" and body.fault.detail.code != ""
  ? {"outcome": "FAILED", "code": body.fault.detail.code, "message": body.fault.detail.message}
: {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"}

mappings.STATUS_QUERY.response:
body.TransferStatusResponse.status = "SUCCESS" and $type(body.TransferStatusResponse.bankRef) = "string" and body.TransferStatusResponse.bankRef != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.TransferStatusResponse.bankRef, "code": body.TransferStatusResponse.code}
: body.TransferStatusResponse.status = "PENDING"
  ? {"outcome": "PENDING", "partnerRef": body.TransferStatusResponse.bankRef, "code": body.TransferStatusResponse.code}
: body.TransferStatusResponse.status = "FAILED" and $type(body.TransferStatusResponse.code) = "string"
  ? {"outcome": "FAILED", "code": body.TransferStatusResponse.code, "message": body.TransferStatusResponse.message}
: body.TransferStatusResponse.status = "NOT_FOUND"
  ? {"outcome": "NOT_FOUND", "code": body.TransferStatusResponse.code}
: {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"}

mappings.REVERSE.response:
body.ReverseTransferResponse.status = "REVERSED" and $type(body.ReverseTransferResponse.reversalRef) = "string"
  ? {"outcome": "SUCCESS", "partnerRef": body.ReverseTransferResponse.reversalRef}
: body.fault.`@code` = "Client" and $type(body.fault.detail.code) = "string" and body.fault.detail.code != ""
  ? {"outcome": "FAILED", "code": body.fault.detail.code, "message": body.fault.detail.message}
: {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"}

mappings.CALLBACK.response:
$type(body.transactionId) != "string" or body.transactionId = "" ? {}
: body.status = "SUCCESS" and $type(body.bankRef) = "string" and body.bankRef != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.bankRef, "reference": body.transactionId,
     "code": body.code, "message": body.message}
: body.status = "FAILED" and $type(body.code) = "string" and body.code != ""
  ? {"outcome": "FAILED", "partnerRef": body.bankRef, "reference": body.transactionId,
     "code": body.code, "message": body.message}
: body.status = "PENDING"
  ? {"outcome": "PENDING", "partnerRef": body.bankRef, "reference": body.transactionId,
     "code": body.code, "message": body.message}
: {}
